{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL-openclaw-luna6-low-ws0/frozen/held-out-2/play/users/u026/system/state/workspace/programs/task-50a27bc7.py",
 "content": "def transform(grid):
    # Detect isolated T tetrominoes and encode each as one output cell.
    h, w = len(grid), len(grid[0])
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=2 or (r,c) in seen: continue
            todo=[(r,c)]; seen.add((r,c)); comp=[]
            while todo:
                y,x=todo.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(y+dy,x+dx)
                    if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==2 and q not in seen:
                        seen.add(q); todo.append(q)
            objs.append(comp)
    # Six positions in output correspond to objects sorted by row, then column;
    # left-side shapes are encoded in column 0 and right-side in column 3.
    out=[[0]*6 for _ in range(3)]
    left=[]; right=[]
    for comp in objs:
        ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
        top,bot,leftx,rightx=min(ys),max(ys),min(xs),max(xs)
        # A T is a three-cell bar and one stem cell; code the bar orientation.
        cells=set(comp); orient=None
        for y in range(top,bot+1):
            if sum((y,x) in cells for x in range(leftx,rightx+1))==3 and rightx-leftx==2:
                orient=('h', y)
        for x in range(leftx,rightx+1):
            if sum((y,x) in cells for y in range(top,bot+1))==3 and bot-top==2:
                orient=('v', x)
        if orient is None: continue
        side=left if (leftx+rightx)/2 < (w-1)/2 else right
        side.append((top,leftx,orient))
    # Demonstrations indicate the output marks a subset by color and placement;
    # maintain dimensions while encoding rows from object order.
    for group, basecol in ((left,0),(right,3)):
        group.sort()
        for i,(r,c,ori) in enumerate(group[:3]):
            if ori[0]=='h':
                out[i][basecol]=3 if basecol==0 else 1
            else:
                out[i][basecol+2]=3 if basecol==0 else 1
    return out
"
}

